sealed class Outcome340 {
    data class Success(val payload: String) : Outcome340()
    data object Failure : Outcome340()
}

fun describe340(outcome: Outcome340): String = when (outcome) {
    is Outcome340.Success -> outcome.payload
    Outcome340.Failure -> "failed"
}
